export interface MriConcept {
  id: string;
  name: string;
  definition: string;
  mri_relevance: string;
  cnn_learning: string;
  medical_interpretation: string;
  example: string;
}

export interface CaseSummary {
  id: string;
  title: string;
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced';
  sequence: string;
  orientation: string;
  age_range: string;
  image_url: string;
  key_concepts: string[];
}

export interface CaseDetail {
  id: string;
  title: string;
  difficulty: 'Beginner' | 'Intermediate' | 'Advanced';
  sequence: string;
  orientation: string;
  age_range: string;
  image_url: string;
  clinical_presentation: string;
  imaging_observations: string;
  learning_objectives: string[];
  key_concepts: string[];
  supported_classes: string[];
  disclaimer: string;
}

export interface StudentCaseSubmission {
  selected_category: string;
  selected_concepts: string[];
  reasoning: string;
}

export interface StudentCaseResult {
  case_id: string;
  student_prediction: string;
  verified_outcome: string;
  is_match: boolean;
  student_reasoning: string;
  student_concepts: string[];
  teaching_points: string;
  differential_considerations: string[];
  what_cnn_learns: string;
  model_limitations: string;
  cnn_prediction?: string | null;
  cnn_confidence?: number | null;
  cnn_scores?: Array<{
    class_name: string;
    score: number;
    percentage: number;
  }> | null;
  gradcam_available: boolean;
  gradcam_image_base64?: string | null;
  gradcam_explanation?: string | null;
  educational_feedback: string;
  disclaimer: string;
}

export interface StudentChatResponse {
  reply: string;
  suggested_actions: string[];
  current_hint_level: number;
  max_hint_level: number;
  disclaimer: string;
}

export interface QuizQuestion {
  id: string;
  topic: string;
  question: string;
  options: string[];
  correct_index: number;
  explanation: string;
}

export interface QuizSubmitResult {
  question_id: string;
  is_correct: boolean;
  correct_index: number;
  explanation: string;
  topic: string;
}

export interface StudentProgressData {
  student_id: string;
  name: string;
  role: string;
  cases_attempted: number;
  cases_completed: number;
  quizzes_attempted: number;
  quizzes_correct: number;
  streak_days: number;
  concepts_mastered: Record<string, number>;
  completed_case_ids: string[];
  topics_to_revise: string[];
  recent_activity: Array<{
    type: string;
    title: string;
    timestamp: string;
    outcome?: string;
  }>;
}

export interface TumorCurriculumItem {
  title: string;
  category: string;
  overview: string;
  general_location: string;
  imaging_characteristics: string[];
  visual_patterns: string[];
  mri_concepts: string[];
  differentials: string[];
  terminology: string[];
  key_learning_points: string[];
  what_cnn_learns: string;
  what_cnn_cannot_tell: string;
}
